//go:build windows

package core

// The .cmd shims and the activation helper scripts are EMBEDDED in the binary
// (single source of truth — nothing is generated by build.ps1 any more). They
// are materialized next to winux.exe on demand:
//
//   - `winux activate` / `winux deactivate` always refresh them first;
//   - `winux shims` refreshes them explicitly (build.ps1 uses this right after
//     building so bin\cmd\ is ready for direct use and the smoke tests).
//
// Materialization is md5-incremental: a file already on disk with identical
// md5 is left untouched (no write, no timestamp churn); only missing or
// changed files are written. The shims live in cmd\ beside the exe, the .ps1
// helpers next to the exe.

import (
	"crypto/md5"
	"embed"
	"encoding/hex"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

//go:embed shimdata
var shimFS embed.FS

// shimExclusions are registered command names that must NOT get a .cmd shim:
// `winux activate/deactivate` are invoked as winux subcommands (a bare
// activate.cmd on the session PATH could collide with other toolchains) and
// `shims` is the materializer itself.
var shimExclusions = map[string]bool{"activate": true, "deactivate": true, "shims": true}

// cmdShimTemplate is the per-command batch shim (LF endings, like cmd.exe
// handles fine and keeps the md5 comparison stable across rebuilds).
const cmdShimTemplate = "@echo off\nsetlocal\n\"%%~dp0..\\winux.exe\" %s %%*\nexit /b %%ERRORLEVEL%%\n"

func init() {
	addCmd("shims", "recreate/refresh the cmd\\ shim files beside this winux.exe (activate does this automatically too)", cmdShims)
}

// shimNameList returns every name that needs a .cmd shim: all registered
// command names (aliases included, so vim gets vim.cmd too) minus the
// exclusions, sorted for deterministic materialization.
func shimNameList() []string {
	var names []string
	for name := range cmdTable {
		if !shimExclusions[name] {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	return names
}

// embeddedFile maps a shimdata entry to its target path relative to the exe dir.
type embeddedFile struct {
	src    string // path inside shimFS
	target string // path relative to the exe directory
}

// embeddedFiles lists all static helpers (winux.cmd / winux-*.cmd go into
// cmd\, the .ps1 helpers sit next to winux.exe).
func embeddedFiles() ([]embeddedFile, error) {
	var out []embeddedFile
	entries, err := fs.ReadDir(shimFS, "shimdata")
	if err != nil {
		return nil, err
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		rel := "shimdata/" + e.Name()
		if strings.HasSuffix(e.Name(), ".ps1") {
			out = append(out, embeddedFile{src: rel, target: e.Name()})
		} else {
			out = append(out, embeddedFile{src: rel, target: filepath.Join("cmd", e.Name())})
		}
	}
	return out, nil
}

// planMaterialize computes the target -> content map and the expected cmd\
// basenames (used to prune stale shims when requested).
func planMaterialize() (map[string][]byte, map[string]bool, error) {
	files := make(map[string][]byte)
	expectedCmd := make(map[string]bool)
	for _, name := range shimNameList() {
		rel := filepath.Join("cmd", name+".cmd")
		files[rel] = []byte(fmt.Sprintf(cmdShimTemplate, name))
		expectedCmd[name] = true
	}
	ef, err := embeddedFiles()
	if err != nil {
		return nil, nil, err
	}
	for _, f := range ef {
		b, err := shimFS.ReadFile(f.src)
		if err != nil {
			return nil, nil, err
		}
		files[f.target] = b
		if strings.HasPrefix(f.target, "cmd"+string(filepath.Separator)) {
			expectedCmd[strings.TrimSuffix(filepath.Base(f.target), filepath.Ext(f.target))] = true
		}
	}
	return files, expectedCmd, nil
}

func md5Hex(b []byte) string {
	s := md5.Sum(b)
	return hex.EncodeToString(s[:])
}

// writeIfChanged writes content to target unless a file with identical md5
// already exists there. Returns whether it wrote.
func writeIfChanged(target string, content []byte) (bool, error) {
	if b, err := os.ReadFile(target); err == nil && md5Hex(b) == md5Hex(content) {
		return false, nil
	}
	return true, os.WriteFile(target, content, 0o644)
}

// materializeShims refreshes the embedded helper files next to winux.exe.
// prune removes stale *.cmd files in cmd\ that are no longer part of the set
// (used by `winux shims`; activate only writes, never deletes).
func materializeShims(prune bool) (created, updated, skipped int, errs []string) {
	exe, err := os.Executable()
	if err != nil {
		return 0, 0, 0, []string{err.Error()}
	}
	exeDir := filepath.Dir(exe)
	files, expectedCmd, err := planMaterialize()
	if err != nil {
		return 0, 0, 0, []string{err.Error()}
	}
	if err := os.MkdirAll(filepath.Join(exeDir, "cmd"), 0o755); err != nil {
		return 0, 0, 0, []string{err.Error()}
	}
	for rel, content := range files {
		target := filepath.Join(exeDir, rel)
		_, statErr := os.Stat(target)
		existed := statErr == nil
		wrote, err := writeIfChanged(target, content)
		if err != nil {
			errs = append(errs, fmt.Sprintf("write %s: %v", target, err))
			continue
		}
		if wrote {
			if existed {
				updated++
			} else {
				created++
			}
		} else {
			skipped++
		}
	}
	if prune {
		cmdDir := filepath.Join(exeDir, "cmd")
		entries, err := os.ReadDir(cmdDir)
		if err == nil {
			for _, e := range entries {
				if e.IsDir() || !strings.HasSuffix(e.Name(), ".cmd") {
					continue
				}
				if !expectedCmd[strings.TrimSuffix(e.Name(), ".cmd")] {
					_ = os.Remove(filepath.Join(cmdDir, e.Name()))
				}
			}
		}
	}
	return created, updated, skipped, errs
}

// ensureShims materializes the embedded helpers (write-only, no pruning) so the
// one-liner `winux activate` prints points at files that actually exist.
func ensureShims() error {
	_, _, _, errs := materializeShims(false)
	if len(errs) > 0 {
		return fmt.Errorf("cannot refresh the cmd\\ shims beside winux.exe: %s", strings.Join(errs, "; "))
	}
	return nil
}

func cmdShims(args []string) int {
	f := NewFlags()
	if !parseOrDie("shims", f, args) {
		return 2
	}
	if handleHelpVersion("shims", "", f) {
		return 0
	}
	created, updated, skipped, errs := materializeShims(true)
	for _, e := range errs {
		warn("shims", "%s", e)
	}
	if len(errs) > 0 {
		return 1
	}
	if created+updated == 0 {
		fmt.Printf("shims up to date: %d files with identical md5, nothing rewritten\n", skipped)
	} else {
		fmt.Printf("shims: %d created, %d updated, %d unchanged\n", created, updated, skipped)
	}
	return 0
}
